import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"为什么研究 DeepSeek Harness","description":"","frontmatter":{},"headers":[],"relativePath":"guide/why-dsh.md","filePath":"guide/why-dsh.md","lastUpdated":null}'),o={name:"guide/why-dsh.md"};function d(r,e,l,i,p,c){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="为什么研究-deepseek-harness" tabindex="-1">为什么研究 DeepSeek Harness <a class="header-anchor" href="#为什么研究-deepseek-harness" aria-label="Permalink to &quot;为什么研究 DeepSeek Harness&quot;">​</a></h1><p>面试官问你&quot;研究过什么开源项目&quot;时，你需要一个<strong>能讲出深度</strong>的答案。DSH 是我选择的答案，这篇文章说明理由，也帮你建立学习它的动机框架。</p><h2 id="dsh-是什么" tabindex="-1">DSH 是什么 <a class="header-anchor" href="#dsh-是什么" aria-label="Permalink to &quot;DSH 是什么&quot;">​</a></h2><p><a href="https://github.com/deepseek-ai/DeepSeek-Harness" target="_blank" rel="noreferrer">DeepSeek Harness（DSH）</a> 是一个<strong>插件化的 agent harness</strong>（智能体基座/运行时），类比 Claude Code、Codex CLI、Cursor Agent 的底层引擎。它解决的核心问题是：</p><blockquote><p>如何把一个 LLM 变成可编程、可审计、可扩展的自主 agent？</p></blockquote><p>它的答案浓缩在仓库根 <code>AGENTS.md</code> 的第一句话：</p><blockquote><p>DeepSeek Harness is a plugin-based agent harness on vendored Cordis: <strong>everything is a plugin</strong>.</p></blockquote><p><strong>一切皆插件。</strong> 包括你以为属于&quot;框架内核&quot;的部分：</p><table tabindex="0"><thead><tr><th>你以为的内核</th><th>在 DSH 里其实</th></tr></thead><tbody><tr><td>模型适配器</td><td>注册在 <code>ctx.llm</code> 上的插件（<code>llm-deepseek</code>、<code>llm-pi-ai</code>、<code>llm-replay</code>）</td></tr><tr><td>工具注册表</td><td><code>ctx.tools</code> 服务 + 各 <code>tool-*</code> 插件</td></tr><tr><td>会话存储</td><td><code>ctx.sessionPersistence</code> seam，jsonl/sqlite 两个可替换后端</td></tr><tr><td><strong>Agent Loop 本身</strong></td><td><code>agent-loop</code> 插件，挂载在 <code>ctx.agentLoop</code> 上</td></tr><tr><td>沙箱</td><td><code>ctx.sandbox</code> seam，Landlock / 本地 / E2B 远程三种后端</td></tr></tbody></table><p>不存在需要打补丁的特权内核。扩展 dsh 的方式是把插件挂到其他插件旁边，而所有注册都是<strong>可逆副作用</strong>——插件卸载时自动撤销。</p><h2 id="为什么值得深度研究-面试视角" tabindex="-1">为什么值得深度研究（面试视角） <a class="header-anchor" href="#为什么值得深度研究-面试视角" aria-label="Permalink to &quot;为什么值得深度研究（面试视角）&quot;">​</a></h2><h3 id="_1-它把-agent-工程的-共识最佳实践-全部落地了" tabindex="-1">1. 它把 agent 工程的&quot;共识最佳实践&quot;全部落地了 <a class="header-anchor" href="#_1-它把-agent-工程的-共识最佳实践-全部落地了" aria-label="Permalink to &quot;1. 它把 agent 工程的&quot;共识最佳实践&quot;全部落地了&quot;">​</a></h3><p>读一个 DSH ≈ 读完一份 agent 系统的设计白皮书：</p><ul><li><strong>事件溯源（Event Sourcing）会话日志</strong>：<code>SessionEvent</code> 是唯一真源，模型历史、UI 回放、fork、恢复、遥测全部从同一日志派生</li><li><strong>Turn / Step 状态机</strong>：轮次（turn）排空输入队列，步骤（step）= 一次模型请求 + 其触发的工具执行</li><li><strong>中间件式拦截链</strong>：waterfall 事件让策略监听器（审批、沙箱、压缩）在不改循环代码的前提下包裹每个环节</li><li><strong>能力 seam 架构</strong>：Service Definition / Provider / Consumer 三角色解耦，替换一个提供方即改变整个产品行为</li><li><strong>上下文工程</strong>：compaction（压缩）、spill（溢出）、token 计量、技能系统</li><li><strong>多代理编排</strong>：subagent、受限 JS workflow 引擎、后台 jobs、持久 goal 循环</li></ul><h3 id="_2-每个子系统都能讲出-为什么这样设计" tabindex="-1">2. 每个子系统都能讲出&quot;为什么这样设计&quot; <a class="header-anchor" href="#_2-每个子系统都能讲出-为什么这样设计" aria-label="Permalink to &quot;2. 每个子系统都能讲出&quot;为什么这样设计&quot;&quot;">​</a></h3><p>面试考察的不是&quot;背架构图&quot;，而是<strong>权衡</strong>。DSH 的官方文档（<code>docs/</code>，约 1.5 万行）把每个机制的触发条件、失败语义、代价都写清楚了。举几个例子：</p><ul><li>为什么 compaction 在 <code>agent/pre-step</code> 做，而不是循环里硬编码？—— 因为它是策略，不是流程</li><li>为什么工具结果要先剪枝再摘要？—— 剪枝是无模型的确定性改写，摘要需要花钱花时间</li><li>为什么 workflow 用受限 JS 脚本而不是自由代码？—— 编排脚本的权限边界 = agent 的权限边界</li><li>为什么&quot;模型可见即已记录&quot;是一条运行时不变量？—— 否则回放、审计、fork 全部失效</li></ul><h3 id="_3-技术栈贴近现代前端-后端-agent-岗位" tabindex="-1">3. 技术栈贴近现代前端+后端 agent 岗位 <a class="header-anchor" href="#_3-技术栈贴近现代前端-后端-agent-岗位" aria-label="Permalink to &quot;3. 技术栈贴近现代前端+后端 agent 岗位&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术</th><th>在 DSH 中的角色</th></tr></thead><tbody><tr><td>TypeScript strict + ESM</td><td>全仓库语言（仅 native 部分用 Rust/C）</td></tr><tr><td>Cordis（vendored）</td><td>插件框架：依赖注入、类型化事件、可逆副作用</td></tr><tr><td>Zod / Typert</td><td>工具 schema、RPC 类型图运行时</td></tr><tr><td>pnpm monorepo + tsdown</td><td>219+ 包的工程化管理</td></tr><tr><td>Vite + React</td><td>Web GUI（<code>apps/web</code> + <code>packages/client</code>）</td></tr><tr><td>node:http / WebSocket</td><td>事件流推送</td></tr><tr><td>SQLite / JSONL</td><td>持久化</td></tr><tr><td>Landlock（Linux 内核安全模块）</td><td>无 root 沙箱</td></tr></tbody></table><h3 id="_4-它是真实的工业级工程-不是玩具-demo" tabindex="-1">4. 它是真实的工业级工程，不是玩具 demo <a class="header-anchor" href="#_4-它是真实的工业级工程-不是玩具-demo" aria-label="Permalink to &quot;4. 它是真实的工业级工程，不是玩具 demo&quot;">​</a></h3><ul><li>CI 覆盖 Windows/macOS/Linux 全平台（甚至用 Wine 测 Windows）</li><li>每文件 100% 覆盖率门槛、快照测试、克隆检测</li><li>双语文档（英/中）由生成器 + 配对流程维护</li><li>事件与类型的交叉校验（<code>@mode</code> 标签、<code>verify-type-equiv</code>）自动防漂移</li></ul><h2 id="阅读源码的地图" tabindex="-1">阅读源码的地图 <a class="header-anchor" href="#阅读源码的地图" aria-label="Permalink to &quot;阅读源码的地图&quot;">​</a></h2><p>整个仓库的入口是 <code>docs/architecture.md</code>。建议阅读顺序：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/cordis-primer.md      → 插件框架 5 个核心概念（必读）</span></span>
<span class="line"><span>docs/architecture.md       → 组装、核心包、事件、轮次流程（必读）</span></span>
<span class="line"><span>docs/glossary.md           → 术语表：seam / scope / turn / step / goal</span></span>
<span class="line"><span>docs/agent-lifecycle.md    → 时序图（核心）</span></span>
<span class="line"><span>docs/tool-execution-pipeline.md → 工具执行管道流程图（核心）</span></span>
<span class="line"><span>docs/capability-seams.md   → 全部服务的注册地图（查表用）</span></span>
<span class="line"><span>docs/subsystems/*.md       → 每个子系统的参考文档（遇到再看）</span></span>
<span class="line"><span>docs/cookbook/*.md         → 扩展实战（加工具/包/适配器）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>源码结构在根 <code>AGENTS.md</code> 有布局图，本资料后续每篇都会给出对应模块的文件地图。</p><h2 id="一个贯穿全程的心智模型" tabindex="-1">一个贯穿全程的心智模型 <a class="header-anchor" href="#一个贯穿全程的心智模型" aria-label="Permalink to &quot;一个贯穿全程的心智模型&quot;">​</a></h2><p>把这句&quot;咒语&quot;刻在脑子里，后文所有内容都是它的展开：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事件流 + 可逆副作用 = DSH 的全部控制流。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 事实（发生了什么）→ 会话事件，追加到日志，可回放</span></span>
<span class="line"><span>2. 实时协调（现在该怎么办）→ agent/* 事件，waterfall 可拦截</span></span>
<span class="line"><span>3. 能力（能做什么）→ 服务 seam，注册表 + 提供方可替换</span></span>
<span class="line"><span>4. 策略（允不允许做）→ 监听器挂在 2 和 3 的事件上，可拆卸</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>下一篇：<a href="/guide/concepts">核心概念速览</a>，我们把 Cordis、事件、seam、会话日志、turn/step 这些术语逐个讲透。</p>`,29)])])}const b=a(o,[["render",d]]);export{h as __pageData,b as default};
